/**
 * rtk-router
 *
 * Automatically routes a small set of *simple, read-only* bash commands through
 * `rtk`, which can compress their output far better than Hypa's generic wrapper
 * (e.g. `ls -laR` 2822B -> 15B). rtk deliberately reformats output; it is not a
 * byte-for-byte replacement for the native command.
 *
 * Design constraints (deliberately conservative):
 *   - Only rewrite when the command is a SINGLE simple command. Anything with
 *     shell metacharacters (pipes, redirects, &&, ;, subshells, command
 *     substitution, globs handled by the shell, env prefixes, etc.) is left
 *     completely alone so shell semantics can never change.
 *   - Only rewrite READ-ONLY verbs. Never touch commands that can mutate state.
 *   - Never rewrite a command that is already an `rtk` or `hypa` invocation.
 *   - Fail open: any uncertainty => leave the command untouched.
 *
 * Ordering note: as verified with Pi 0.84.x, user extensions in
 * ~/.pi/agent/extensions load before npm packages, so Hypa sees the final
 * command. Hypa is configured with exclude_commands=["rtk"] so it passes these
 * through instead of double-wrapping.
 */

import { isToolCallEventType, type ExtensionAPI } from "@earendil-works/pi-coding-agent";

/**
 * Direct, read-only verbs for which rtk accepts native flags without ambiguity.
 * `grep` and `rg` are intentionally excluded: a leading-dash search pattern
 * (e.g. grep "-i" file) is parsed by rtk as an option and loses results.
 */
const SAFE_DIRECT = new Set(["ls", "find", "wc", "diff"]);

/**
 * `git` is only safe for a read-only subset. `git diff`/`status`/`log`/`show`
 * do not mutate the repo. Everything else (add/commit/checkout/reset/...) must
 * be left untouched.
 */
const SAFE_GIT = new Set(["status", "diff", "log", "show"]);

/**
 * Shell metacharacters that mean "this is not a single simple command".
 * If any appear, we bail out entirely.
 *
 * Note: `*` and `?` are NOT included. They are expanded by the shell before the
 * process runs, so `rtk ls *.ts` still receives the same expanded argv that
 * `ls *.ts` would have.
 */
const SHELL_META = /[|&;<>()$`\\!\n]/;

/** Detects `VAR=value cmd ...` env prefixes, which we do not rewrite. */
const ENV_PREFIX = /^\s*[A-Za-z_][A-Za-z0-9_]*=/;

export function shouldRewrite(command: string): boolean {
  const cmd = command.trim();
  if (cmd.length === 0) return false;

  // Already routed through a compressor.
  if (/^(rtk|hypa)\b/.test(cmd)) return false;

  // Any shell composition => hands off.
  if (SHELL_META.test(cmd)) return false;
  if (ENV_PREFIX.test(cmd)) return false;

  // `cd foo && ...` is caught by SHELL_META, but a bare leading `cd` would
  // change directory semantics for the rewritten process; skip anything that
  // isn't a recognised read-only verb anyway (handled below).

  const tokens = cmd.split(/\s+/);
  const verb = tokens[0];

  // rtk reserves bare `-h` for its own help, unlike native ls where it means
  // human-readable sizes. Preserve native behavior for this form.
  if (verb === "ls" && tokens.includes("-h")) return false;

  if (SAFE_DIRECT.has(verb)) return true;

  if (verb === "git") {
    const sub = tokens[1];
    // `git` alone, or a non-read-only subcommand, is left alone.
    return sub !== undefined && SAFE_GIT.has(sub);
  }

  return false;
}

export function rewrite(command: string): string {
  return `rtk ${command.trim()}`;
}

export default function (pi: ExtensionAPI) {
  pi.on("tool_call", async (event) => {
    if (!isToolCallEventType("bash", event)) return;

    const original = event.input.command;
    if (typeof original !== "string") return;

    try {
      if (shouldRewrite(original)) {
        event.input.command = rewrite(original);
      }
    } catch {
      // Fail open: never block or alter a command because of a router bug.
    }
  });

  pi.registerCommand("rtk-router", {
    description: "Show which commands rtk-router would rewrite",
    handler: async (args, ctx) => {
      const probe = args?.trim();
      if (probe) {
        const verdict = shouldRewrite(probe) ? `-> ${rewrite(probe)}` : "(left untouched)";
        ctx.ui.notify(`rtk-router: ${probe}\n${verdict}`, "info");
        return;
      }
      ctx.ui.notify(
        [
          "rtk-router active",
          `Direct verbs: ${[...SAFE_DIRECT].join(", ")}`,
          `git subcommands: ${[...SAFE_GIT].join(", ")}`,
          "Skipped: pipes, redirects, &&, ;, subshells, env prefixes, mutating commands",
          "Probe with: /rtk-router <command>",
        ].join("\n"),
        "info",
      );
    },
  });
}

